#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Tunable constants for scheduling
// -----------------------------------------------------------------------------

// Tile sizes for the SPD matrix construction (init_array).
// These are purely performance knobs: changing them does not change results.
constexpr int INIT_TILE_J = 32;  // tile size along columns (x / j)
constexpr int INIT_TILE_I = 32;  // tile size along rows    (y / i)

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
//
// This computes the same initialization as the original C code, but uses a
// tiled, vectorized, and parallelized schedule for the O(n^3) SPD
// construction step to improve cache locality and CPU utilization.
//
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var j("j"), i("i");
    Func A0("A0"), B("B");

    // -------------------------------------------------------------------------
    // Lower-triangular base matrix A0
    //
    // C code:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // For 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // Fold into a single pointwise expression:
    // -------------------------------------------------------------------------

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // Note: we still use (j <= i) to cover lower triangle and 0 above.
    A0(j, i) = select(
        j <= i,
        // On or below diagonal
        select(j == i,
               // Diagonal element: 1
               one,
               // Strictly lower triangular part:
               // (-j)/n + 1
               cast<num_t>(-j) / n_val + one),
        // Above diagonal
        zero);

    // -------------------------------------------------------------------------
    // Make the matrix symmetric positive semi-definite:
    //
    //   B[r][s] = sum_t A[r][t] * A[s][t];
    //   A <- B
    //
    // Mapping to Halide:
    //   B(r,s) in C  -> B(j,i) in Halide
    //   A[r][t]      -> A0(t,r) -> A0(t,i)
    //   A[s][t]      -> A0(t,s) -> A0(t,j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)
    // -------------------------------------------------------------------------

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -------------------------------------------------------------------------
    // Schedule for B (matrix multiply-like kernel)
    //
    // We:
    //   - tile the (j,i) space to improve locality,
    //   - parallelize across tiles in the outer row dimension,
    //   - vectorize across j inside each tile.
    //
    // A0 is left inline: its computation is just arithmetic on (i,j),
    // so inlining avoids any extra memory traffic.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    B.compute_root()
        .tile(j, i, jo, io, ji, ii, INIT_TILE_J, INIT_TILE_I)
        // Parallel over tile-rows (io): each worker operates on a band of rows.
        .parallel(io)
        // Vectorize along contiguous x (j) within each tile.
        .vectorize(ji, vec_width);

    // JIT-compile and realize into the provided buffer A.
    B.realize(A, target);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (outside the timed region).
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j, so we cannot
    // express the full kernel as a single pure Halide Func. Instead, we:
    //
    //   - Keep the outer loops over i and j on the host (as required to
    //     preserve the sequential dependencies).
    //   - Use Halide Funcs to compute each inner summation over k:
    //       sum_{k<j} A[i][k] * A[k][j]
    //       sum_{k<i} A[i][k] * A[k][j]
    //
    //   - We use ImageParam + Param<int> for i and j, and realize a scalar
    //     Func for each (i, j) where needed.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; note that we never write
    // to A inside Halide; we only read from it in the Funcs below. The
    // in-place updates to A are done on the host after each scalar realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // Choose a vector width appropriate for this machine and element type.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // -------------------------------------------------------------------------
    // Func to compute:
    //   A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    // for the case j < i (the "L" part), before dividing by A[j][j].
    //
    // Mapping to Halide buffer indices:
    //   A[i][j]   -> A_param(j_param, i_param)
    //   A[i][k]   -> A_param(k,       i_param)
    //   A[k][j]   -> A_param(j_param, k)
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    RDom k_left(0, j_param, "k_left");

    left_elem() = A_param(j_param, i_param);
    left_elem() += cast<num_t>(-1) *
                   A_param(k_left, i_param) *
                   A_param(j_param, k_left);

    // -------------------------------------------------------------------------
    // Func to compute:
    //   A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    // for the case j >= i (the "U" part).
    //
    // Mapping is the same as above; only the reduction extent changes.
    // -------------------------------------------------------------------------
    Func right_elem("right_elem");
    RDom k_right(0, i_param, "k_right");

    right_elem() = A_param(j_param, i_param);
    right_elem() += cast<num_t>(-1) *
                    A_param(k_right, i_param) *
                    A_param(j_param, k_right);

    // -------------------------------------------------------------------------
    // Schedule for the reduction Funcs
    //
    // Each Func is scalar-valued (no pure Vars), but has a 1D reduction
    // over k. We vectorize across the reduction dimension to exploit
    // SIMD inside the dot product. The outer (i,j) loops remain on the
    // host to preserve the LU dependencies.
    // -------------------------------------------------------------------------
    left_elem.update().vectorize(k_left, vec_width);
    right_elem.update().vectorize(k_right, vec_width);

    // JIT-compile the scalar pipelines once; we will reuse them for all (i, j).
    left_elem.compile_jit(target);
    right_elem.compile_jit(target);

    // Reusable 0-D buffers for the scalar realizations (to avoid per-call
    // heap allocation inside the timed region).
    Buffer<num_t> left_scalar  = Buffer<num_t>::scalar();
    Buffer<num_t> right_scalar = Buffer<num_t>::scalar();

    // -------------------------------------------------------------------------
    // Run kernel and time it (only the LU factorization, not init_array())
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // First inner loop: j = 0 .. i-1
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            left_elem.realize(left_scalar, target);
            num_t val = left_scalar();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // Second inner loop: j = i .. n-1
        for (int j = i; j < n; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            right_elem.realize(right_scalar, target);
            num_t val = right_scalar();  // zero-dimensional buffer

            // Store back into A[i][j] (no division here)
            A(j, i) = val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
