    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.
    // We fold all this into a single expression:

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // A0(j, i) corresponds to A[i][j] in the C code.
    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower-triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    // B(r, s) in C  -> B(j, i) in Halide
    // A[r][t]       -> A0(t, r) -> A0(t, i)
    // A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -------------------------
    // Simple scheduling for CPU
    // -------------------------
    Target target = get_jit_target_from_environment();
    const int vec = target.natural_vector_size<num_t>();

    // Compute the triangular matrix row-major in i, vectorized in j.
    A0.compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Compute the SPD product similarly. This still does O(n^3) work,
    // but with good cache behavior and vectorization along columns.
    B.compute_root()
        .parallel(i)
        .vectorize(j, vec);
    B.update()
        .parallel(i);

    // JIT-compile once, then realize directly into the provided buffer A.
    B.compile_jit(target);
    B.realize(A);
}

