    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (SPD matrix) with a Halide pipeline.
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into an optimized, Halide-assisted implementation.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // The algorithm has loop-carried dependencies along i and j, so we cannot
    // express the *entire* kernel as a single pure Halide Func. Instead we:
    //
    //   - Keep the outer loops over i and the lower-triangular j-loop on the
    //     host (these are inherently sequential).
    //   - Use plain C++ for the strictly sequential L-part (j < i), which is
    //     a forward-substitution on a unit-lower-triangular system.
    //   - Use a Halide Func to compute the upper part (j >= i) for each row i
    //     in a vectorized fashion. This part has no loop-carried dependencies
    //     across j and is well-suited for Halide.
    //
    // The Halide pipeline for the U-part reads from the current A via an
    // ImageParam and produces an updated row i into a temporary buffer, which
    // is then copied back into A on the host.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A. We never write to this from
    // Halide; we only read from it. Host-side updates to A are visible via this
    // ImageParam because it aliases the same underlying Buffer storage.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameter for the current row index i.
    Param<int> i_param("i_param");

    // Func to compute, for a fixed row i, all upper entries A[i][j] for j >= i:
    //
    //   A[i][j] <- A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // In terms of our mapping:
    //   A[i][j] in C   -> A(j, i) in Halide
    //   A[i][k]        -> A(k, i)
    //   A[k][j]        -> A(j, k)
    //
    // We define a 1D Func over j that performs the inner summation over k.
    Var j("j");
    Func upper_update("upper_update");

    // Pure definition: start from the current A[i][j]
    upper_update(j) = A_param(j, i_param);

    // Reduction over k = 0 .. i-1:
    // upper_update(j) -= A[i][k] * A[k][j]
    //
    // A[i][k] -> A_param(k, i_param)
    // A[k][j] -> A_param(j, k)
    RDom k(0, i_param, "k");
    upper_update(j) -= A_param(k, i_param) * A_param(j, k);

    // -----------------------
    // Schedule for upper row:
    // -----------------------
    Target target = get_jit_target_from_environment();
    const int vec = target.natural_vector_size<num_t>();

    // Vectorize across j for both the pure and update definitions.  The
    // reduction is across k, so it is safe to vectorize j: each j's sum is
    // independent and still iterates k in increasing order.
    upper_update.vectorize(j, vec);
    upper_update.update().vectorize(j, vec);

    // (Optionally, one could also parallelize over j here, but since we call
    // this per-row inside an outer sequential loop over i, vectorization is
    // typically the main win and keeps the schedule simple.)

    // JIT-compile once; we will reuse this pipeline for all rows i.
    upper_update.compile_jit(target);

    // Temporary buffer to hold the updated upper row A[i][j], j = 0..n-1.
    // We reuse this buffer for every i to avoid repeated allocations.
    Halide::Buffer<num_t> u_row(n);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // -------------------
        // Lower-triangular L:
        // -------------------
        //
        // for (j = 0; j < i; j++) {
        //   for (k = 0; k < j; k++) {
        //     A[i][j] -= A[i][k] * A[k][j];
        //   }
        //   A[i][j] /= A[j][j];
        // }
        //
        // Mapping A[i][j] -> A(j, i), etc.

        for (int j_c = 0; j_c < i; j_c++) {
            num_t val = A(j_c, i);  // A[i][j]

            for (int k_c = 0; k_c < j_c; k_c++) {
                // A[i][k] * A[k][j] -> A(k, i) * A(j, k)
                val -= A(k_c, i) * A(j_c, k_c);
            }

            // Divide by A[j][j]
            val /= A(j_c, j_c);

            // Store back into A[i][j] (i.e. A(j, i) in Halide layout)
            A(j_c, i) = val;
        }

        // ---------------
        // Upper-triangular U:
        // ---------------
        //
        // for (j = i; j < n; j++) {
        //   for (k = 0; k < i; k++) {
        //     A[i][j] -= A[i][k] * A[k][j];
        //   }
        // }
        //
        // This part has no loop-carried dependence across j, so we compute the
        // entire row i for j ∈ [i, n) using the Halide pipeline above.

        // Bind the current row index for the Halide pipeline.
        i_param.set(i);

        // Create a view of u_row that covers j = i .. n-1. By setting the
        // min/index of this 1D Buffer to i, we cause Halide to evaluate
        // upper_update(j) exactly over j ∈ [i, n).
        const int extent = n - i;
        if (extent > 0) {
            Halide::Buffer<num_t> u_slice = u_row.cropped(0, i, extent);

            // Compute the updated row A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            // into the temporary buffer.
            upper_update.realize(u_slice);

            // Copy the computed upper row back into A for j ≥ i.
            for (int j_c = i; j_c < n; j_c++) {
                A(j_c, i) = u_row(j_c);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j_c = 0; j_c < n; j_c++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j_c, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
