#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Tunable constants for scheduling
// -----------------------------------------------------------------------------
static constexpr int INIT_VEC_WIDTH_FALLBACK = 8;  // used if natural_vector_size() returns 0

// -----------------------------------------------------------------------------
// Array initialization: translate Polybench init_array() into a Halide pipeline
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index    -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    // -------------------------------------------------------------------------
    // Step 1: build the lower-triangular matrix A0 equivalent to the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we drop the % n.
    // A[i][j] in C -> A0(j, i) in Halide.
    // -------------------------------------------------------------------------
    A0(j, i) = select(
        j <= i,
        select(j == i,
               one,                       // diagonal
               cast<num_t>(-j) / n_val + one),  // strictly lower
        zero);                             // above diagonal

    // -------------------------------------------------------------------------
    // Step 2: make the matrix positive semi-definite by B = A0 * A0^T:
    //
    // B[r][s] = sum_t A0[r][t] * A0[s][t];
    //
    // Mapping:
    //   B(r, s) in C  -> B(j, i) in Halide
    //   A0[r][t]      -> A0(t, r) -> A0(t, i)
    //   A0[s][t]      -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)
    // -------------------------------------------------------------------------
    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // -------------------------------------------------------------------------
    // Scheduling for initialization
    //
    // The matrix build is O(n^3); a reasonably cache- and vector-friendly
    // schedule helps considerably but stays simple.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    int vec = target.natural_vector_size<num_t>();
    if (vec <= 0) {
        vec = INIT_VEC_WIDTH_FALLBACK;
    }

    // Compute A0 once at root so that it can be reused efficiently by B.
    A0.compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Compute all of B at the root. Vectorize across columns (j) and
    // parallelize over rows (i). Reordering the update loops to make
    // j the innermost loop improves spatial locality for B and A0.
    B.compute_root();

    B.update()
        .reorder(j, i, t)
        .parallel(i)
        .vectorize(j, vec);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C has DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (SPD matrix)
    init_array(n, A);

    // -------------------------------------------------------------------------
    // Translate kernel_lu into Halide-assisted code.
    //
    // Original C kernel:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++) {
    //       A[i][j] -= A[i][k] * A[k][j];
    //     }
    //   }
    // }
    //
    // This algorithm has loop-carried dependencies along i and j (a classic
    // sequential LU factorization without pivoting), so we cannot express
    // the full kernel as a single pure Halide Func. We proceed as follows:
    //
    //   - Keep the outer loops over i and the "L part" loop over j on the host
    //     to respect the dependencies.
    //
    //   - Use Halide Funcs to:
    //       * Compute the scalar update for the "L" entries:
    //           A[i][j] - sum_{k<j} A[i][k] * A[k][j]
    //       * Compute *entire rows* of the "U" part for fixed i:
    //           for all j >= i, in one vectorized Halide realization:
    //             A[i][j] - sum_{k<i} A[i][k] * A[k][j]
    //
    //   - We use ImageParam for the matrix A and Param<int> for indices.
    //     A is updated on the host; Halide pipelines always see the current
    //     values in A.
    // -------------------------------------------------------------------------

    // Current matrix A as an ImageParam.  We only read from it in Halide;
    // all writes (the in-place LU updates) occur on the host.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters for the current (i, j) indices
    Param<int> i_param("i");
    Param<int> j_param("j");

    // -------------------------------------------------------------------------
    // Func 1: left_elem()
    //
    // Compute one scalar L-entry:
    //
    //   left_elem() = A[i][j] - sum_{k=0}^{j-1} A[i][k] * A[k][j]
    //                all done in Halide; the final division A[i][j] /= A[j][j]
    //                is performed on the host.
    //
    // Mapping:
    //   A[i][j] in C         -> A_param(j_param, i_param)
    //   A[i][k] in C         -> A_param(k_left,  i_param)
    //   A[k][j] in C         -> A_param(j_param, k_left)
    // -------------------------------------------------------------------------
    Func left_elem("left_elem");
    {
        left_elem() = A_param(j_param, i_param);

        RDom k_left(0, j_param, "k_left");
        left_elem() -= A_param(k_left, i_param) * A_param(j_param, k_left);
    }

    // -------------------------------------------------------------------------
    // Func 2: right_row(jj)
    //
    // For fixed i, compute the entire "U" row segment j = i..n-1 in one shot:
    //
    //   for all j >= i:
    //     right_row(j - i) = A[i][j] - sum_{k=0}^{i-1} A[i][k] * A[k][j]
    //
    // Here we re-index columns with jj = j - i to keep the Halide domain
    // starting at 0; later we store back into A[i][j] with j = jj + i.
    //
    // Dependencies:
    //   - All L(i, k) for k < i are already computed by the first inner loop
    //     for this i, so there are no loop-carried dependencies across j.
    //   - This makes it legal to compute all j >= i in parallel and/or
    //     vectorized inside Halide for a fixed i.
    //
    // Mapping:
    //   A[i][j]       -> A_param(jj + i_param, i_param)
    //   A[i][k]       -> A_param(k_right,       i_param)
    //   A[k][j]       -> A_param(jj + i_param,  k_right)
    // -------------------------------------------------------------------------
    Var jj("jj");
    Func right_row("right_row");
    {
        right_row(jj) = A_param(jj + i_param, i_param);

        RDom k_right(0, i_param, "k_right");
        right_row(jj) -= A_param(k_right, i_param) *
                         A_param(jj + i_param, k_right);
    }

    // -------------------------------------------------------------------------
    // Scheduling for the LU-helper pipelines
    //
    // left_elem is scalar, so there is not much to schedule; right_row
    // computes a 1D slice and is a good target for vectorization.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    int vec = target.natural_vector_size<num_t>();
    if (vec <= 0) {
        vec = INIT_VEC_WIDTH_FALLBACK;
    }

    // For scalar left_elem() we just compute at root (default) and JIT.
    left_elem.compute_root();

    // For right_row, vectorize the pure and update definitions across jj.
    right_row.compute_root();
    right_row.vectorize(jj, vec);
    right_row.update().vectorize(jj, vec);

    // JIT-compile the helper pipelines once and reuse them for all (i, j).
    left_elem.compile_jit(target);
    right_row.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // ---------------------------------------------------------------------
        // First inner loop: compute the strict-lower part (L) of row i
        //   for j = 0 .. i-1:
        //     A[i][j] = (A[i][j] - sum_{k<j} A[i][k] * A[k][j]) / A[j][j];
        // ---------------------------------------------------------------------
        for (int j = 0; j < i; j++) {
            i_param.set(i);
            j_param.set(j);

            // Compute A[i][j] - sum_{k<j} A[i][k] * A[k][j]
            Halide::Buffer<num_t> tmp = left_elem.realize();
            num_t val = tmp();  // zero-dimensional buffer

            // Divide by A[j][j]
            // Mapping: A[j][j] in C -> A(j, j) in Halide
            val /= A(j, j);

            // Store back into A[i][j] (i.e. A(j, i) in Halide)
            A(j, i) = val;
        }

        // ---------------------------------------------------------------------
        // Second inner loop: compute the upper part (U) of row i
        //
        //   for j = i .. n-1:
        //     A[i][j] = A[i][j] - sum_{k<i} A[i][k] * A[k][j];
        //
        // We compute this entire row segment in a single Halide realization
        // via right_row(jj), which is vectorized over jj.
        // ---------------------------------------------------------------------
        if (i < n) {
            i_param.set(i);

            // right_row produces a vector of length (n - i) with entries
            // corresponding to j = i .. n-1 as:
            //   right_row(j - i) = A[i][j] - sum_{k<i} A[i][k] * A[k][j]
            Halide::Buffer<num_t> row_vals = right_row.realize({n - i});

            // Store the results back into A[i][j].
            for (int j = i; j < n; j++) {
                int jj = j - i;
                A(j, i) = row_vals(jj);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
