// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // We map the original C array A[i][j] to Halide buffer A(j, i):
    //   - i is the row index  -> second dimension (y)
    //   - j is the column index -> first dimension (x)

    Var i("i"), j("j");
    Func A0("A0"), B("B");

    // First, generate the lower-triangular matrix used as in the C code:
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Note: for 0 <= j < n, (-j % n) == -j, so we can drop the % n.

    Expr one   = cast<num_t>(1);
    Expr zero  = cast<num_t>(0);
    Expr n_val = cast<num_t>(n);

    A0(j, i) = select(
        j <= i,
        // On or below the diagonal
        select(i == j,
               // Diagonal element
               one,
               // Strictly lower triangular part
               cast<num_t>(-j) / n_val + one),
        // Above the diagonal
        zero);

    // Now make the matrix positive semi-definite by computing:
    //
    // B[r][s] = sum_t A[r][t] * A[s][t];
    //
    // and then copying B back into A. In terms of our mapping:
    //   B(r, s) in C  -> B(j, i) in Halide
    //   A[r][t]       -> A0(t, r) -> A0(t, i)
    //   A[s][t]       -> A0(t, s) -> A0(t, j)
    //
    // So:
    //   B(j, i) = sum_{t=0..n-1} A0(t, i) * A0(t, j)

    RDom t(0, n, "t");
    B(j, i) = cast<num_t>(0);
    B(j, i) += A0(t, i) * A0(t, j);

    // --------------------
    // Scheduling for speed
    // --------------------
    Target target = get_host_target();
    const int vec_width = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // A0 is a simple triangular initialization: parallelize rows, vectorize columns.
    A0.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // B is a dense n×n matrix product. Parallelize over rows (i) and vectorize over
    // columns (j) for both the pure and update definitions.
    B.compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    B.update()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize B directly into the provided buffer A. This is equivalent
    // to computing B and then copying B into A as in the original C code.
    B.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Matrix A: original C is DATA_TYPE A[N][N];
    // We map to Halide Buffer with shape (cols, rows) = (n, n)
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A (SPD lower-triangular construction)
    init_array(n, A);

    // -------------------------------------------------------------------------
    // LU factorization kernel
    //
    // Original Polybench C kernel (row-oriented form):
    //
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++)
    //       A[i][j] -= A[i][k] * A[k][j];
    //     A[i][j] /= A[j][j];
    //   }
    //   for (j = i; j < n; j++) {
    //     for (k = 0; k < i; k++)
    //       A[i][j] -= A[i][k] * A[k][j];
    //   }
    // }
    //
    // This is a classical Doolittle LU without pivoting, expressed with i
    // outermost. It has strong loop-carried dependencies along i and j, so
    // expressing the entire kernel as a single pure Halide Func is not
    // possible.
    //
    // Instead, we use an equivalent, "pivot-oriented" formulation with k
    // outermost, which preserves the per-element arithmetic order but exposes
    // much more parallelism across rows/columns:
    //
    // for (k = 0; k < n; k++) {
    //   // Compute U's k-th row (including diagonal):
    //   for (j = k; j < n; j++) {
    //     for (p = 0; p < k; p++)
    //       A[k][j] -= A[k][p] * A[p][j];
    //   }
    //
    //   // Compute L's k-th column (below diagonal):
    //   for (i = k+1; i < n; i++) {
    //     for (p = 0; p < k; p++)
    //       A[i][k] -= A[i][p] * A[p][k];
    //     A[i][k] /= A[k][k];
    //   }
    // }
    //
    // For each (i, j) this computes exactly the same arithmetic expression as
    // the original kernel, with the same accumulation order over p, so
    // floating‑point results are identical; only the traversal order of
    // (i, j) changes.
    //
    // This k‑outermost form has the key property that within a fixed k:
    //   - All U[k][j] for j ≥ k are independent of each other.
    //   - All L[i][k] for i > k are independent of each other.
    //
    // That makes the dot-products over p excellent candidates for Halide
    // pipelines that compute entire rows/columns at once, enabling
    // vectorization and parallelization over j / i, while keeping the outer
    // pivot loop on the host.
    // -------------------------------------------------------------------------

    // ImageParam representing the current matrix A; we only *read* through it
    // in Halide Funcs and write back to A on the host after each realization.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameter for the current pivot index k.
    Param<int> k_param("k");

    // We will define two 1D Funcs:
    //   row_update(t): updates the U row for pivot k, for columns j = k + t.
    //   col_update(t): updates the L column for pivot k, for rows   i = k+1+t.

    Var t("t");

    // --------------------------
    // U row update: A[k][j], j>=k
    // --------------------------
    //
    // For fixed k and j >= k:
    //
    //   A[k][j] <- A[k][j] - sum_{p=0}^{k-1} A[k][p] * A[p][j]
    //
    // With the mapping A[i][j] (C) -> A(j, i) (Halide):
    //   A[k][j]     -> A(j, k)
    //   A[k][p]     -> A(p, k)
    //   A[p][j]     -> A(j, p)
    //
    // We index j as (t + k_param), where t runs from 0 .. (n-k-1) in the
    // realized buffer.

    Func row_update("row_update");
    {
        Expr j_index = t + k_param;  // logical column j = k + t

        // Pure definition: start from the current A[k][j]
        row_update(t) = A_param(j_index, k_param);

        // Reduction over p = 0 .. k-1
        RDom p_row(0, k_param, "p_row");
        row_update(t) += cast<num_t>(-1) *
                         A_param(p_row, k_param) *   // A[k][p]  -> A(p, k)
                         A_param(j_index, p_row);    // A[p][j]  -> A(j, p)
    }

    // ---------------------------
    // L column update: A[i][k], i>k
    // ---------------------------
    //
    // For fixed k and i > k:
    //
    //   A[i][k] <- A[i][k] - sum_{p=0}^{k-1} A[i][p] * A[p][k];
    //   A[i][k] <- A[i][k] / A[k][k];
    //
    // Mapping:
    //   A[i][k]     -> A(k, i)
    //   A[i][p]     -> A(p, i)
    //   A[p][k]     -> A(k, p)
    //   A[k][k]     -> A(k, k)
    //
    // We index i as (k + 1 + t), where t runs from 0 .. (n-k-2) in the
    // realized buffer.

    Func col_update("col_update");
    {
        Expr i_index = t + k_param + 1;  // logical row i = k + 1 + t

        // Start from the current A[i][k]
        col_update(t) = A_param(k_param, i_index);

        // Reduction over p = 0 .. k-1
        RDom p_col(0, k_param, "p_col");
        col_update(t) += cast<num_t>(-1) *
                         A_param(p_col, i_index) *   // A[i][p] -> A(p, i)
                         A_param(k_param, p_col);    // A[p][k] -> A(k, p)

        // Divide by the pivot A[k][k] (which is U[k][k])
        col_update(t) /= A_param(k_param, k_param);
    }

    // -------------------------
    // Schedule for LU pipelines
    // -------------------------
    Target lu_target = get_jit_target_from_environment();
    const int lu_vec_width =
        std::max(1, lu_target.natural_vector_size(type_of<num_t>()));

    // We split the 1D loop over t into [outer, inner] to combine
    // parallelism across outer tiles and vectorization within tiles.
    {
        Var to("to"), ti("ti");

        row_update
            .compute_root()
            .split(t, to, ti, 64)
            .parallel(to)
            .vectorize(ti, lu_vec_width);

        row_update.update()
            .split(t, to, ti, 64)
            .parallel(to)
            .vectorize(ti, lu_vec_width);
    }

    {
        Var to2("to2"), ti2("ti2");

        col_update
            .compute_root()
            .split(t, to2, ti2, 64)
            .parallel(to2)
            .vectorize(ti2, lu_vec_width);

        col_update.update()
            .split(t, to2, ti2, 64)
            .parallel(to2)
            .vectorize(ti2, lu_vec_width);
    }

    // JIT‑compile the row/column update pipelines once; we will reuse them
    // for all pivots k.
    row_update.compile_jit(lu_target);
    col_update.compile_jit(lu_target);

    // Temporary 1D buffers reused across iterations to avoid repeated
    // allocations.
    Halide::Buffer<num_t> row_buf(n);     // for j = k .. n-1  (size at most n)
    Halide::Buffer<num_t> col_buf(n > 0 ? n - 1 : 0);  // for i = k+1 .. n-1

    // -------------------------------------------------------------------------
    // Run kernel and time it
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        k_param.set(k);

        // -----------------------
        // 1) Update U's k-th row
        // -----------------------
        //
        // We need to compute row_update(t) for t = 0 .. (n-k-1), corresponding
        // to j = k .. n-1.

        const int row_width = n - k;
        if (row_width > 0) {
            // Use a cropped view of row_buf of the appropriate length.
            auto row_sub = row_buf.cropped(0, 0, row_width);

            // Compute the updated row values into row_sub.
            row_update.realize(row_sub);

            // Copy back into A: A[k][j] in C -> A(j, k) in Halide
            for (int offset = 0; offset < row_width; ++offset) {
                int j = k + offset;
                A(j, k) = row_sub(offset);
            }
        }

        // After this, A(k, k) (i.e., U[k][k]) has been updated and can be
        // used safely in the column update below.

        // -------------------------
        // 2) Update L's k-th column
        // -------------------------
        //
        // Only if there are rows strictly below the diagonal.
        if (k + 1 < n) {
            const int col_height = n - k - 1;  // number of i > k
            auto col_sub = col_buf.cropped(0, 0, col_height);

            // Compute updated column entries into col_sub.
            col_update.realize(col_sub);

            // Copy back into A: A[i][k] in C -> A(k, i) in Halide
            for (int offset = 0; offset < col_height; ++offset) {
                int i = k + 1 + offset;
                A(k, i) = col_sub(offset);
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Optional: print the resulting matrix, in the same order as the C version
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // A[i][j] in C corresponds to A(j, i) in Halide
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print timing (in seconds)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
